A generated JavaScript function for a shipping calculator. Read it signature-first, then returns, then the body, to determine whether the body actually delivers on what those two things promise.

```javascript
function computeShippingCost(order, destination) {
  if (!destination.isServiceable) {
    return { cost: null, reason: 'unserviceable' };
  }
  const weight = order.items.reduce((sum, item) => sum + item.weightKg, 0);
  if (weight === 0) {
    return { cost: 0, reason: 'no_physical_items' };
  }
  const base = weight * destination.ratePerKg;
  const surcharge = order.isPriority ? base * 0.4 : 0;
  return { cost: Math.round((base + surcharge) * 100) / 100, reason: 'computed' };
}
```

